// ============================================================================
// RLE4K Decoder Output Data Accumulator (Variable → 512-bit) 
// ============================================================================
// Description: Accumulates variable-length decoded data into 512-bit words
//              Based on rle4k_decoder_output_fifo_512.md requirements
// Author: Generated by Claude Code
// Date: 2026-01-09
// ============================================================================

`timescale 1ns / 1ps
// tips, here output are 512 bits.

module decoder_output_accumulator (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        clear,            // Synchronous clear (pulse): discard accumulated bits

    // Input: variable-length data (1-512 bits)
    input  wire [511:0] data_in,
    input  wire [9:0]  data_length_in,  // Data length: 1-512 bits
    input  wire        valid_in,
    output reg         ready_out,        // Ready signal: data flow control (backpressure)

    // Output: 512-bit aligned data
    output reg  [511:0] data_out,
    output reg         valid_out,
    input  wire        ready_in,

    // Status feedback (required)
    output reg  [9:0]  accumulated_bits  // Current accumulated bits in accumulator (0-512)
);

// ============================================================================
// Internal Signals
// ============================================================================

reg [511:0] accumulator;      // 512-bit accumulator
reg [9:0]   accumulated_bits_reg;  // Accumulated bits counter (0-512)

// Temporary variables for calculations
integer bits_to_add;
integer remaining_bits;

// Generate mask for extracting low N bits from 512-bit data
// mask(N) = (1 << N) - 1, which gives N bits of 1s at low positions
// Example: mask(5) = 0x1F = 0b11111
function [511:0] gen_mask;
    input [9:0] num_bits;
    begin
        if (num_bits == 10'd0)
            gen_mask = 512'd0;
        else if (num_bits >= 10'd512)
            gen_mask = {512{1'b1}};
        else
            gen_mask = (512'd1 << num_bits) - 512'd1;
    end
endfunction

// ============================================================================
// Data Accumulation Logic
// ============================================================================
// LSB format (Least Significant Bit first): First data at low bits, later data at higher bits
// Extract low data_length_in bits from data_in and accumulate at low bits
// When accumulated_bits + data_length_in >= 512, output 512 bits and keep remaining data
// Boundary conditions: data_length_in = 0 or > 512 are ignored

always @(posedge clk) begin
    if (!rst_n || clear) begin
        accumulator          <= 512'd0;
        accumulated_bits_reg <= 10'd0;
        data_out             <= 512'd0;
        valid_out            <= 1'b0;
        ready_out            <= 1'b1;
        accumulated_bits     <= 10'd0;
    end else begin
        valid_out <= 1'b0;
        
        // Handle data_length_in == 0: consume handshake but don't process data
        if (valid_in && ready_out && data_length_in == 10'd0) begin
            // Consume handshake for data_length_in == 0, but don't process data
            // This ensures upstream can proceed even if it sends invalid length
            ready_out <= 1'b1;  // Ready immediately since no processing needed
        end else if (valid_in && ready_out && data_length_in > 10'd0 && data_length_in <= 10'd512) begin
            // Check if we need to output (will need ready_in) or just accumulate (don't need ready_in)
            if ((accumulated_bits_reg + data_length_in) >= 11'd512) begin
                // Will output: need ready_in to be true
                if (ready_in) begin
                    ready_out <= 1'b0;  // Block during processing
                    bits_to_add = 512 - accumulated_bits_reg;
                    remaining_bits = (accumulated_bits_reg + data_length_in) - 512;

                    // Output: combine accumulator data and new data to form 512-bit output
                    // LSB format: accumulator has accumulated_bits_reg bits at [accumulated_bits_reg-1:0]
                    // New data (bits_to_add bits) goes at [accumulated_bits_reg+bits_to_add-1:accumulated_bits_reg]
                    // Combine: accumulator[accumulated_bits_reg-1:0] | (data_in[bits_to_add-1:0] << accumulated_bits_reg)
                    data_out <= accumulator | ((data_in & gen_mask(bits_to_add)) << accumulated_bits_reg);
                    valid_out <= 1'b1;

                    // Remaining data: extract remaining_bits from data_in starting at bit position bits_to_add
                    // Put remaining data at low bits for next accumulation (LSB format)
                    if (remaining_bits > 0) begin
                        accumulator <= (data_in >> bits_to_add) & gen_mask(remaining_bits);
                    end else begin
                        accumulator <= 512'd0;
                    end
                    accumulated_bits_reg <= remaining_bits;
                    
                    // If output is immediately accepted, ready for next data in same cycle
                    // Otherwise, wait for output to be accepted
                    if (ready_in) begin
                        ready_out <= 1'b1;  // Output accepted immediately, ready for next
                    end
                end
                // If ready_in is false, we wait (ready_out stays 1, but we don't process)
            end else begin
                // Just accumulate, no output - processing complete, ready immediately
                // Don't need ready_in for accumulation-only
                ready_out <= 1'b0;  // Block during processing
                // LSB format: new data goes at [accumulated_bits_reg+data_length_in-1:accumulated_bits_reg]
                // Old data stays at [accumulated_bits_reg-1:0]
                accumulator <= accumulator | ((data_in & gen_mask(data_length_in)) << accumulated_bits_reg);
                accumulated_bits_reg <= accumulated_bits_reg + data_length_in;
                ready_out <= 1'b1;  // Accumulation complete, ready for next data immediately
            end
        end
        
        // Ready signal control: ready for next data after output is accepted or when idle
        if (valid_out && ready_in && ready_out == 1'b0) begin
            // Output accepted, ready for next data (if not already set above)
            ready_out <= 1'b1;
        end else if (!valid_in && ready_out == 1'b0 && !valid_out) begin
            // No input, not outputting, ready for new data
            ready_out <= 1'b1;
        end
        
        // Update accumulated_bits status output
        accumulated_bits <= accumulated_bits_reg;
    end
end

endmodule
